package com.smarthealth.dao;
import com.smarthealth.model.Medicine;import com.smarthealth.exception.DataAccessException;import java.sql.*;import java.util.*;
public class JdbcMedicineDao implements GenericDao<Medicine,Long>{private final ConnectionManager db;public JdbcMedicineDao(ConnectionManager d){db=d;}public Optional<Medicine> findById(Long id){try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM medicines WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}catch(SQLException e){throw new DataAccessException("Medicine lookup failed",e);}}public List<Medicine> findAll(){return findForPatient(1);}public List<Medicine> findForPatient(long id){List<Medicine>x=new ArrayList<>();try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM medicines WHERE patient_id=? ORDER BY name")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){while(r.next())x.add(map(r));}return x;}catch(SQLException e){throw new DataAccessException("Medicine query failed",e);}}public Medicine save(Medicine v){String q=v.getId()==0?"INSERT INTO medicines(patient_id,name,dosage,instructions,start_date,end_date,frequency) VALUES(?,?,?,?,?,?,?)":"UPDATE medicines SET name=?,dosage=?,instructions=?,start_date=?,end_date=?,frequency=? WHERE id=? AND patient_id=?";try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement(q,v.getId()==0?Statement.RETURN_GENERATED_KEYS:Statement.NO_GENERATED_KEYS)){if(v.getId()==0){p.setLong(1,v.getPatientId());p.setString(2,v.getName());p.setString(3,v.getDosage());p.setString(4,v.getInstructions());p.setDate(5,v.getStartDate()==null?null:java.sql.Date.valueOf(v.getStartDate()));p.setDate(6,v.getEndDate()==null?null:java.sql.Date.valueOf(v.getEndDate()));p.setString(7,v.getFrequency());p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){if(k.next())v.setId(k.getLong(1));}}else{p.setString(1,v.getName());p.setString(2,v.getDosage());p.setString(3,v.getInstructions());p.setDate(4,v.getStartDate()==null?null:java.sql.Date.valueOf(v.getStartDate()));p.setDate(5,v.getEndDate()==null?null:java.sql.Date.valueOf(v.getEndDate()));p.setString(6,v.getFrequency());p.setLong(7,v.getId());p.setLong(8,v.getPatientId());p.executeUpdate();}return v;}catch(SQLException e){throw new DataAccessException("Medicine save failed",e);}}public boolean delete(Long id){try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM medicines WHERE id=?")){p.setLong(1,id);return p.executeUpdate()>0;}catch(SQLException e){throw new DataAccessException("Medicine delete failed",e);}}private Medicine map(ResultSet r)throws SQLException{return new Medicine(r.getLong("id"),r.getLong("patient_id"),r.getString("name"),r.getString("dosage"),r.getString("instructions"),r.getDate("start_date")==null?null:r.getDate("start_date").toLocalDate(),r.getDate("end_date")==null?null:r.getDate("end_date").toLocalDate(),r.getString("frequency"));}}
